// Generated by build.py from ui/; edit those files instead.
import { host, PALETTE_AREA, ROUTES_AREA, SIDEBAR_NAV_AREA, STATUSBAR_AREAS } from '@hermes/plugin-sdk'
import * as React from 'react'

const ID = 'hermes-usage-gate'
const ROUTE = '/usage-gate'

function createUsageGate(React, api) {
  const h = React.createElement
  const { useCallback, useEffect, useState } = React

  const C = {
    text: 'var(--ui-text-primary, var(--color-foreground, currentColor))',
    muted: 'var(--ui-text-secondary, var(--color-muted-foreground, #8a8f98))',
    border: 'var(--ui-stroke-secondary, var(--color-border, rgba(128, 128, 128, 0.28)))',
    track: 'var(--ui-stroke-tertiary, rgba(128, 128, 128, 0.18))',
    accent: 'var(--ui-accent, var(--color-primary, #4f7cff))',
    green: 'var(--ui-green, #2e9d5b)',
    orange: 'var(--ui-orange, #e08a1e)',
    red: 'var(--ui-red, #d64545)'
  }
  const DECISIONS = {
    open: { label: 'Open', color: C.green },
    paused: { label: 'Paused', color: C.red }
  }

  const s = {
    page: { padding: '20px 24px', color: C.text, fontSize: 13, lineHeight: 1.45, maxWidth: 1180 },
    header: { display: 'flex', alignItems: 'baseline', gap: 12, flexWrap: 'wrap', marginBottom: 4 },
    title: { fontSize: 18, fontWeight: 600, margin: 0 },
    note: { color: C.muted, fontSize: 12 },
    section: { fontSize: 14, fontWeight: 600, margin: '22px 0 10px' },
    cards: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(340px, 1fr))', gap: 12 },
    card: { border: `1px solid ${C.border}`, borderRadius: 8, padding: '12px 14px' },
    row: { display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' },
    badge: color => ({ display: 'inline-block', padding: '1px 8px', borderRadius: 999, fontSize: 11, fontWeight: 600,
      color, border: `1px solid ${color}`, whiteSpace: 'nowrap' }),
    button: (tone, solid) => ({ padding: '4px 10px', borderRadius: 6, cursor: 'pointer', fontSize: 12,
      border: `1px solid ${tone || C.border}`, background: solid ? tone : 'transparent', color: solid ? '#fff' : tone || C.text }),
    table: { width: '100%', borderCollapse: 'collapse' },
    th: { textAlign: 'left', fontWeight: 500, color: C.muted, padding: '6px 8px', borderBottom: `1px solid ${C.border}`, fontSize: 12 },
    td: { padding: '7px 8px', borderBottom: `1px solid ${C.border}`, verticalAlign: 'top' },
    mono: { fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace', fontSize: 12 },
    error: { color: C.red, fontSize: 12, margin: '8px 0' },
    warn: { color: C.orange, fontSize: 12 },
    empty: { color: C.muted, padding: '14px 0' }
  }

  function ago(iso) {
    if (!iso) return 'never'
    const seconds = Math.max(0, (Date.now() - new Date(iso).getTime()) / 1000)
    if (seconds < 90) return 'just now'
    if (seconds < 5400) return `${Math.round(seconds / 60)} min ago`
    if (seconds < 129600) return `${Math.round(seconds / 3600)} h ago`
    return `${Math.round(seconds / 86400)} d ago`
  }

  function when(iso) {
    return iso ? new Date(iso).toLocaleString([], { dateStyle: 'short', timeStyle: 'short' }) : ''
  }

  function errorText(error) {
    return String(error && error.message || error)
  }

  function Bar({ used, threshold, color }) {
    return h('div', { style: { position: 'relative', height: 8, borderRadius: 4, background: C.track, margin: '4px 0' } },
      h('div', { style: { width: `${Math.min(100, used)}%`, height: '100%', borderRadius: 4, background: color } }),
      threshold != null && h('div', { title: `Threshold ${threshold}%`, style: { position: 'absolute', top: -3, bottom: -3,
        left: `${threshold}%`, width: 2, background: C.text, opacity: 0.6 } }))
  }

  function pausedName(plan) {
    return plan.decision === 'paused' ? plan.label : `${plan.label} (${(plan.paused_models || []).join(', ')})`
  }

  function Plan({ plan, refreshMinutes }) {
    const partial = plan.decision !== 'paused' && (plan.paused_models || []).length > 0
    const decision = partial ? { label: `${plan.paused_models.join(', ')} paused`, color: C.orange }
      : DECISIONS[plan.decision] || { label: 'No reading yet', color: C.muted }
    const stale = plan.last_reading_at && Date.now() - new Date(plan.last_reading_at).getTime() > refreshMinutes * 2 * 60000
    const windows = plan.windows || []
    return h('div', { style: s.card },
      h('div', { style: { ...s.row, justifyContent: 'space-between' } },
        h('strong', null, plan.label),
        h('span', { style: s.badge(decision.color) }, decision.label)),
      h('div', { style: { ...s.note, margin: '2px 0 10px' } }, plan.bots.length ? plan.bots.join(', ') : 'No bots on this plan'),
      partial && h('div', { style: { ...s.warn, marginBottom: 10 } },
        `Held: ${(plan.held_bots || []).join(', ') || 'no bot'}. The plan's other bots still start their cards.`),
      windows.length ? windows.map(w => {
        const threshold = w.kind === 'session' ? plan.thresholds.session_percent : plan.thresholds.week_percent
        const over = w.used_percent >= threshold
        return h('div', { key: w.label, style: { marginBottom: 10 } },
          h('div', { style: { ...s.row, justifyContent: 'space-between' } },
            h('span', null, w.label),
            h('span', { style: { color: over ? C.red : C.text, fontVariantNumeric: 'tabular-nums' } },
              `${Math.round(w.used_percent)}% of ${threshold}%`)),
          h(Bar, { used: w.used_percent, threshold, color: over ? C.red : C.accent }),
          w.resets_at && h('div', { style: s.note }, `Resets ${when(w.resets_at)}`))
      }) : h('div', { style: s.note }, 'No usage reading yet.'),
      plan.reason && h('div', { style: { ...s.note, marginTop: 6 } }, plan.reason),
      h('div', { style: s.note }, `Last good reading ${ago(plan.last_reading_at)}`),
      stale && h('div', { style: s.warn }, 'The latest checks could not read this plan; the last decision is being kept.'))
  }

  function usd(v) {
    return `$${Number(v || 0).toFixed(2)}`
  }

  function OpenRouter({ data, label }) {
    const warned = (data.warnings || []).length > 0
    const badge = data.error && !data.last_reading_at ? { label: 'Unreadable', color: C.muted }
      : warned ? { label: 'Warning', color: C.orange } : { label: 'OK', color: C.green }
    const usedShare = data.total_credits ? Math.min(100, (100 * data.total_usage) / data.total_credits) : 0
    return h('div', { style: s.card },
      h('div', { style: { ...s.row, justifyContent: 'space-between' } },
        h('strong', null, label),
        h('span', { style: s.badge(badge.color) }, badge.label)),
      h('div', { style: { ...s.note, margin: '2px 0 10px' } }, 'Watched, never gated: no bot runs on it.'),
      data.last_reading_at && h('div', { style: { marginBottom: 10 } },
        h('div', { style: { ...s.row, justifyContent: 'space-between' } },
          h('span', null, 'Credits'),
          h('span', { style: { fontVariantNumeric: 'tabular-nums' } }, `${usd(data.total_usage)} of ${usd(data.total_credits)} spent`)),
        h(Bar, { used: usedShare, threshold: null, color: data.balance < (data.balance_warn_usd ?? -1) ? C.orange : C.accent }),
        h('div', { style: s.note }, `Balance ${usd(data.balance)}`)),
      (data.keys || []).map(key => h('div', { key: key.name, style: { marginBottom: 10 } },
        h('div', { style: { ...s.row, justifyContent: 'space-between' } },
          h('span', null, `Key ${key.name}`),
          key.limit != null && h('span', { style: { fontVariantNumeric: 'tabular-nums' } },
            `${usd(key.spent)} of ${usd(key.limit)}${key.limit_reset ? ` ${key.limit_reset}` : ''}`)),
        key.limit != null && h(Bar, { used: key.percent || 0, threshold: null, color: C.accent }),
        h('div', { style: s.note }, `Today ${usd(key.usage_daily)} · week ${usd(key.usage_weekly)} · month ${usd(key.usage_monthly)}`))),
      (data.warnings || []).map(w => h('div', { key: w, style: s.warn }, w)),
      data.error && h('div', { style: s.warn }, data.error),
      h('div', { style: s.note }, `Last good reading ${ago(data.last_reading_at)}`))
  }

  function Held({ cards }) {
    if (!cards.length) return h('div', { style: s.empty }, 'No cards are being held.')
    return h('table', { style: s.table },
      h('thead', null, h('tr', null, ['Card', 'Title', 'Bot', 'Column'].map(t => h('th', { key: t, style: s.th }, t)))),
      h('tbody', null, cards.map(c => h('tr', { key: c.id },
        h('td', { style: { ...s.td, ...s.mono } }, c.id),
        h('td', { style: s.td }, c.title),
        h('td', { style: s.td }, c.assignee),
        h('td', { style: s.td }, c.status === 'review' ? 'Review' : 'Ready')))))
  }

  const INTERRUPTION_STATUS = {
    waiting: { label: 'Waiting for the plan', color: C.orange },
    resumed: { label: 'Resumed', color: C.green },
    expired: { label: 'Expired', color: C.muted },
    'gave-up': { label: 'Gave up', color: C.red },
    'skipped-user': { label: 'You continued it', color: C.muted },
    'skipped-recovered': { label: 'Already answered', color: C.muted }
  }

  function Interrupted({ chats }) {
    if (!chats.length) return h('div', { style: s.empty }, 'No chat was stopped by a plan limit this week.')
    return h('table', { style: s.table },
      h('thead', null, h('tr', null, ['Bot', 'Chat', 'Plan', 'Stopped', 'Status'].map(t => h('th', { key: t, style: s.th }, t)))),
      h('tbody', null, chats.map(c => {
        const status = INTERRUPTION_STATUS[c.status] || { label: c.status, color: C.muted }
        return h('tr', { key: `${c.profile}:${c.session_id}` },
          h('td', { style: s.td }, c.profile),
          h('td', { style: s.td }, c.title || h('span', { style: s.mono }, c.session_id)),
          h('td', { style: s.td }, c.label),
          h('td', { style: s.td }, when(c.interrupted_at)),
          h('td', { style: s.td },
            h('span', { style: s.badge(status.color) }, status.label),
            c.resumes > 0 && h('span', { style: { ...s.note, marginLeft: 6 } }, `${c.resumes} resume${c.resumes > 1 ? 's' : ''}`),
            c.resolved_at && h('div', { style: s.note }, when(c.resolved_at))))
      })))
  }

  const PERIODS = [['1', 'Last 24 h'], ['7', 'Last 7 days'], ['30', 'Last 30 days'], ['all', 'All time']]
  function compact(n) {
    if (n >= 1e6) return `${(n / 1e6).toFixed(n >= 1e7 ? 1 : 2)}M`
    if (n >= 1e3) return `${(n / 1e3).toFixed(n >= 1e4 ? 0 : 1)}K`
    return String(n)
  }

  const SEGMENTS = [['cache_read', 'Cache read', C.accent], ['input', 'Input', C.green],
    ['cache_write', 'Cache write', C.orange], ['output', 'Output', C.red]]

  function ModelChart({ rows }) {
    const models = []
    rows.forEach(row => {
      const key = `${row.model}\u0000${row.provider}`
      let m = models.find(x => x.key === key)
      if (!m) models.push(m = { key, model: row.model, label: row.label || row.provider, calls: 0, reasoning: 0,
        ...Object.fromEntries(SEGMENTS.map(([k]) => [k, 0])) })
      m.calls += row.calls
      m.reasoning += row.reasoning
      SEGMENTS.forEach(([k]) => { m[k] += row[k] })
    })
    models.forEach(m => { m.total = SEGMENTS.reduce((sum, [k]) => sum + m[k], 0) })
    models.sort((a, b) => b.total - a.total)
    const max = Math.max(1, ...models.map(m => m.total))
    return h('div', { style: s.card },
      h('div', { style: { ...s.row, marginBottom: 10, gap: 14 } }, SEGMENTS.map(([k, label, color]) =>
        h('span', { key: k, style: { ...s.row, gap: 5, ...s.note } },
          h('span', { style: { width: 10, height: 10, borderRadius: 2, background: color, display: 'inline-block' } }), label))),
      models.map((m, i) => h('div', { key: m.key, style: { marginBottom: i === models.length - 1 ? 0 : 10 } },
        h('div', { style: { ...s.row, justifyContent: 'space-between' } },
          h('span', null, h('span', { style: s.mono }, m.model), h('span', { style: s.note }, ` · ${m.label}`)),
          h('span', { style: { fontVariantNumeric: 'tabular-nums' }, title: `${m.total.toLocaleString()} tokens` },
            `${compact(m.total)} tokens · ${m.calls} call${m.calls === 1 ? '' : 's'}`)),
        h('div', { style: { display: 'flex', height: 12, borderRadius: 3, overflow: 'hidden', background: C.track,
          width: `${Math.max(1, (m.total / max) * 100)}%`, marginTop: 3 } },
          SEGMENTS.map(([k, label, color]) => m[k] > 0 && h('div', { key: k,
            title: `${label}: ${m[k].toLocaleString()}${k === 'output' && m.reasoning ? ` (reasoning ${m.reasoning.toLocaleString()})` : ''}`,
            style: { width: `${(m[k] / m.total) * 100}%`, minWidth: 2, background: color } }))),
        h('div', { style: s.note }, SEGMENTS.filter(([k]) => m[k] > 0).map(([k, label]) =>
          `${label} ${compact(m[k])}${k === 'output' && m.reasoning ? ` (reasoning ${compact(m.reasoning)})` : ''}`).join(' · ')))))
  }

  function Tokens() {
    const [period, setPeriod] = useState('7')
    const [bot, setBot] = useState('')
    const [data, setData] = useState(null)
    const [error, setError] = useState(null)
    useEffect(() => {
      let alive = true
      setData(null)
      api.get(`/tokens/${period}`).then(d => { if (alive) { setData(d); setError(null) } })
        .catch(err => alive && setError(errorText(err)))
      return () => { alive = false }
    }, [period])
    const allRows = data ? data.rows : []
    const botNames = [...new Set(allRows.map(r => r.bot))]
    const rows = bot ? allRows.filter(r => r.bot === bot) : allRows
    return h('div', null,
      h('div', { style: { ...s.row, marginBottom: 8 } },
        PERIODS.map(([value, label]) =>
          h('button', { key: value, type: 'button', onClick: () => setPeriod(value),
            style: s.button(period === value ? C.accent : null, period === value) }, label)),
        h('select', { value: bot, onChange: e => setBot(e.target.value), 'aria-label': 'Bot',
          style: { ...s.button(), marginLeft: 8, background: 'transparent', color: C.text } },
          h('option', { value: '' }, 'All bots'),
          [...new Set([...botNames, ...(bot ? [bot] : [])])].map(name => h('option', { key: name, value: name }, name)))),
      error && h('div', { style: s.error }, error),
      !data && !error && h('div', { style: s.note }, 'Loading…'),
      data && !rows.length && h('div', { style: s.empty }, bot ? `No model calls by ${bot} in this period.` : 'No model calls in this period.'),
      rows.length > 0 && h(ModelChart, { rows }),
      h('div', { style: { ...s.note, marginTop: 8 } },
        'Every model call sends the whole conversation again; the part the provider already holds is billed as a cache read, ' +
        'which is why cache reads dwarf output. Reasoning is part of output. A session counts in the period it started. ' +
        'Not recorded by Hermes: curator runs, Honcho’s own model calls, and calls that failed.'))
  }

  function SettingsSummary({ settings, plans }) {
    const pct = v => `${Math.round(Number(v))}%`
    const rows = [
      ['Gate', settings.enabled ? 'Enabled' : 'Disabled'],
      ['Session threshold', pct(settings.session_percent)],
      ['Weekly threshold', pct(settings.week_percent)],
      ['Check every', `${settings.refresh_minutes} min`],
      ["Keep a pause when usage can't be read", `${settings.hold_minutes} min`],
      ['Comment on held cards', settings.comment_held_cards ? 'Yes' : 'No'],
      ['Resume chats stopped by a plan limit', settings.resume_interrupted_chats ? 'Yes' : 'No']
    ]
    const openrouter = settings.openrouter || {}
    if (openrouter.enabled) {
      rows.push([`${openrouter.label || 'OpenRouter'}: warn when the balance is under`, usd(openrouter.balance_warn_usd)])
      rows.push([`${openrouter.label || 'OpenRouter'}: warn when a key reaches`, `${Math.round(Number(openrouter.key_warn_percent))}% of its limit`])
    }
    if (settings.resume_interrupted_chats) {
      rows.push(['Resume within', `${settings.resume_within_hours} h of the first stop`])
      rows.push(['Resume message', settings.resume_message])
    }
    plans.forEach(plan => {
      const own = (settings.providers || {})[plan.provider] || {}
      if (own.session_percent !== undefined || own.week_percent !== undefined) {
        rows.push([`${plan.label} thresholds`, `session ${pct(plan.thresholds.session_percent)}, week ${pct(plan.thresholds.week_percent)}`])
      }
    })
    return h('div', { style: { ...s.card, maxWidth: 640 } },
      h('table', { style: s.table }, h('tbody', null, rows.map(([label, value]) => h('tr', { key: label },
        h('td', { style: { ...s.td, color: C.muted, width: '55%' } }, label),
        h('td', { style: s.td }, value))))),
      h('div', { style: { ...s.note, marginTop: 8 } },
        'Read-only. These live in the usage_gate section of the default profile’s Hermes config.'))
  }

  return function UsageGate() {
    const [status, setStatus] = useState(null)
    const [error, setError] = useState(null)
    const [checking, setChecking] = useState(false)
    const load = useCallback(() => api.get('/status').then(data => { setStatus(data); setError(null) })
      .catch(err => setError(errorText(err))), [])
    useEffect(() => {
      load()
      const timer = setInterval(load, 30000)
      return () => clearInterval(timer)
    }, [load])
    const check = () => {
      setChecking(true)
      api.post('/check').then(setStatus).catch(err => setError(errorText(err))).finally(() => setChecking(false))
    }
    if (!status) return h('div', { style: s.page }, error ? h('div', { style: s.error }, error) : h('div', { style: s.note }, 'Loading…'))
    const paused = status.plans.filter(p => p.decision === 'paused' || (p.paused_models || []).length)
    return h('div', { style: s.page },
      h('div', { style: s.header },
        h('h1', { style: s.title }, 'Usage Gate'),
        h('span', { style: s.badge(!status.settings.enabled ? C.muted : paused.some(p => p.decision === 'paused') ? C.red
          : paused.length ? C.orange : C.green) },
          !status.settings.enabled ? 'Disabled' : paused.length ? `Paused: ${paused.map(pausedName).join(', ')}` : 'All plans open'),
        h('span', { style: s.note }, `Checked ${ago(status.checked_at)} · every ${status.settings.refresh_minutes} min`),
        h('button', { type: 'button', onClick: check, disabled: checking, style: s.button() }, checking ? 'Checking…' : 'Check now')),
      h('div', { style: s.note }, 'New board cards for a plan’s bots wait while its usage is over a threshold. Chats, schedules, webhooks and email runs are never held; a chat a plan limit stopped is resumed once the plan is open again.'),
      error && h('div', { style: s.error }, error),
      h('div', { style: s.section }, 'Plans'),
      h('div', { style: s.cards },
        status.plans.map(plan => h(Plan, { key: plan.provider, plan, refreshMinutes: status.settings.refresh_minutes })),
        status.openrouter && h(OpenRouter, { data: status.openrouter, label: (status.settings.openrouter || {}).label || 'OpenRouter' })),
      h('div', { style: s.section }, 'Held cards'),
      h(Held, { cards: status.held || [] }),
      h('div', { style: s.section }, 'Interrupted chats'),
      h(Interrupted, { chats: status.interrupted || [] }),
      h('div', { style: s.section }, 'Tokens'),
      h(Tokens),
      h('div', { style: s.section }, 'Settings'),
      h(SettingsSummary, { settings: status.settings, plans: status.plans }))
  }
}

function PausedPlans({ ctx }) {
  const [paused, setPaused] = React.useState([])
  React.useEffect(() => {
    let alive = true
    const load = () => ctx.rest('/status')
      .then(r => alive && setPaused([
        ...r.plans.filter(p => p.decision === 'paused' || (p.paused_models || []).length)
          .map(p => `⏸ ${p.decision === 'paused' ? p.label : `${p.label} (${p.paused_models.join(', ')})`} paused`),
        ...((r.openrouter && (r.openrouter.warnings || []).length) ? [`⚠ ${(r.settings.openrouter || {}).label || 'OpenRouter'} low`] : [])]))
      .catch(() => {})
    load()
    const timer = setInterval(load, 60000)
    return () => { alive = false; clearInterval(timer) }
  }, [])
  if (!paused.length) return null
  return React.createElement('button', {
    type: 'button', onClick: () => host.navigate(ROUTE), title: 'Open the Usage Gate page',
    style: { display: 'inline-flex', alignItems: 'center', height: '100%', padding: '0 6px', fontSize: 11, border: 'none',
      background: 'none', cursor: 'pointer', color: 'var(--ui-red, #d64545)' }
  }, paused.join(' · '))
}

export default {
  id: ID,
  name: 'Usage Gate',
  description: 'Each plan\'s usage, whether the board may start its bots\' cards, the cards being held, and the gate\'s settings.',
  register(ctx) {
    const api = {
      get: path => ctx.rest(path),
      post: (path, body) => ctx.rest(path, { method: 'POST', body: body || {} })
    }
    const App = createUsageGate(React, api)
    ctx.registerMany([
      { id: 'page', area: ROUTES_AREA, data: { path: ROUTE }, render: () => React.createElement(App) },
      { id: 'nav', area: SIDEBAR_NAV_AREA, data: { path: ROUTE, label: 'Usage Gate', codicon: 'pulse' } },
      { id: 'open', area: PALETTE_AREA, data: { id: `${ID}.open`, label: 'Open Usage Gate', run: () => host.navigate(ROUTE) } },
      { id: 'paused', area: STATUSBAR_AREAS.right, order: 121, render: () => React.createElement(PausedPlans, { ctx }) }
    ])
  }
}
